from scipy.optimize import least_squares
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
G={'1':np.ones_like(t),'x':x,'v':v,'xv':x*v,'x2':x*x,'v2':v*v,'x3':x**3,'v3':v**3}
T={'cos':np.cos,'sin':np.sin,'t':lambda s:s,'none':lambda s:np.ones_like(s)}
def build(par,spec):
    cols=[v**par[0]]
    k=1
    for tn,gn in spec:
        if tn=='none' or tn=='t': w=1.0
        else: w=par[k]; k+=1
        cols.append(T[tn](w*t)*G[gn] if tn!='t' else t*G[gn])
    return np.column_stack(cols)
def nfit(spec,nw):
    best=None
    rng=np.random.default_rng(0)
    for trial in range(12):
        p0=[rng.uniform(0.2,2)]+list(rng.uniform(0.1,2,nw))
        def f(par):
            M=build(par,spec); return M@np.linalg.lstsq(M,a,rcond=None)[0]-a
        try:
            r=least_squares(f,p0)
            val=np.mean(r.fun**2)/np.var(a)
            if best is None or val<best[0]: best=(val,r.x)
        except: pass
    return best
